2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * Flags a create-owner request as a <em>possible</em> (soft) duplicate: one that is not a hard
12	 * duplicate (see {@link RejectDuplicateIdentity}) yet whose {@link OwnerIdentity#key(Owner)
13	 * identity key} <em>differs</em> from an existing owner's while sharing that owner's last name
14	 * phonetically ({@code soundex(lastName)}, see {@link NameSoundex}) and its {@code postcode}
15	 * (compared case-insensitively with surrounding whitespace trimmed). Such an owner is still
16	 * created; it is merely marked so callers can review it. When a match is found the owner's
17	 * {@code possibleDuplicate} is set true and
18	 * {@code possibleDuplicateOf} to the matching owner's id (the earliest such owner by id when
19	 * several match); otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf}
20	 * is left unset.
21	 *
22	 * <p>A create that opts in with {@code sharesHousehold} is a <em>declared</em> household member,
23	 * not a suspected one, so it is never flagged: {@code possibleDuplicate} stays false.
24	 *
25	 * <p>Runs after {@link RejectDuplicateIdentity} (so a hard duplicate has already been rejected)
26	 * and within the create transaction, but before {@link SaveOwner}, so the new owner is not yet
27	 * persisted and cannot match itself.
28	 */
29	public class AssignPossibleDuplicate {
30	
31	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
32	        owner.setPossibleDuplicate(false);
33	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
34	            return; // a declared household member is not a suspected duplicate
35	        }
36	        if (normalize(owner.getPostcode()).isEmpty()) {
37	            return; // no postcode to share on
38	        }
39	        Integer matchId = earliestSoftMatch(owner, ownerRepository);
40	        if (matchId != null) {
41	            owner.setPossibleDuplicate(true);
42	            owner.setPossibleDuplicateOf(matchId);
43	        }
44	    }
45	
46	    /**
47	     * The id of the earliest existing owner (lowest id) that {@code owner} is a soft duplicate of,
48	     * or {@code null} when none matches.
49	     */
50	    private static Integer earliestSoftMatch(Owner owner, OwnerRepository ownerRepository) {
51	        Integer matchId = null;
52	        for (Owner existing : ownerRepository.findAll()) {
53	            if (!isSoftMatch(owner, existing)) {
54	                continue;
55	            }
56	            if (matchId == null || existing.getId() < matchId) {
57	                matchId = existing.getId();
58	            }
59	        }
60	        return matchId;
61	    }
62	
63	    /**
64	     * Whether {@code existing} makes {@code owner} a soft (possible) duplicate: a different,
65	     * live owner sharing its last name phonetically ({@code soundex(lastName)}) and its postcode
66	     * while carrying a <em>different</em> identity key (an equal key would be a hard duplicate,
67	     * already rejected upstream).
68	     */
69	    private static boolean isSoftMatch(Owner owner, Owner existing) {
70	        if (owner.getId() != null && owner.getId().equals(existing.getId())) {
71	            return false;
72	        }
73	        if (existing.isDeleted()) {
74	            return false; // a soft-deleted owner is not a possible duplicate
75	        }
76	        if (!NameSoundex.of(existing.getLastName()).equals(NameSoundex.of(owner.getLastName()))) {
77	            return false;
78	        }
79	        if (!normalize(existing.getPostcode()).equals(normalize(owner.getPostcode()))) {
80	            return false;
81	        }
82	        // an equal identity key is a hard duplicate, already rejected upstream
83	        return !OwnerIdentity.key(owner).equals(OwnerIdentity.key(existing));
84	    }
85	
86	    private static String normalize(String value) {
87	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
88	    }
89	}
